<?php require_once 'includes/db.php';require_once 'includes/auth.php';require_login();$msg='';$err='';$campaigns=$conn->query('SELECT id,title FROM campaigns WHERE status="active" ORDER BY title');$selected=(int)($_GET['campaign']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){$campaign=(int)$_POST['campaign_id'];$amount=(float)$_POST['amount'];$method=$_POST['payment_method']??'';$phone=trim($_POST['phone']??'');if($amount<=0||!in_array($method,['Card','UPI','Net Banking'],true)){$err='Enter a valid amount and payment method.';}else{$s=$conn->prepare('INSERT INTO donations(user_id,campaign_id,amount,payment_method,phone) VALUES(?,?,?,?,?)');$uid=$_SESSION['user_id'];$s->bind_param('iidss',$uid,$campaign,$amount,$method,$phone);if($s->execute()){$msg='Donation recorded successfully. Thank you for your support!';}else{$err='Could not record donation.';}}}
$page_title='Donate';include 'includes/header.php';?><div class="card form-card"><h2>Make a Donation</h2><p>Give money or support to a cause or charity.</p><?php if($msg):?><div class="alert success-msg"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><div class="form-group"><label>Campaign</label><select name="campaign_id" required><?php while($c=$campaigns->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$selected===$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Donation Amount (₹)</label><input type="number" step="0.01" min="1" name="amount" required></div><div class="form-group"><label>Donor Phone</label><input name="phone" required></div><div class="form-group"><label>Payment Option</label><select name="payment_method" required><option>Card</option><option>UPI</option><option>Net Banking</option></select></div><button class="btn success" type="submit">Donate</button></form></div><?php include 'includes/footer.php';?>
